import sys
import io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

import openpyxl
from openpyxl.utils import get_column_letter

FILE = '교원조회_20250318_점검용.xlsx'
wb_formula = openpyxl.load_workbook(FILE, data_only=False)
wb_value = openpyxl.load_workbook(FILE, data_only=True)

# 임용쿼터계산 -- show more rows and all formulas detail
ws_f = wb_formula['임용쿼터계산']
ws_v = wb_value['임용쿼터계산']

print('=== 임용쿼터계산 - ALL FORMULAS complete list ===')
all_formulas = {}
for row in ws_f.iter_rows():
    for cell in row:
        if cell.value and isinstance(cell.value, str) and cell.value.startswith('='):
            col_l = get_column_letter(cell.column)
            vv = ws_v.cell(row=cell.row, column=cell.column).value
            if col_l not in all_formulas:
                all_formulas[col_l] = []
            all_formulas[col_l].append((cell.row, cell.value, vv))

from openpyxl.utils import column_index_from_string
for col_l in sorted(all_formulas.keys(), key=lambda x: column_index_from_string(x)):
    entries = all_formulas[col_l]
    print(f'\nColumn {col_l} ({len(entries)} formula cells):')
    for row_num, formula, val in entries:
        print(f'  Row {row_num}: {formula}  => {val}')

print()
print('=== 임용쿼터계산 - rows around summary rows (E/F/G columns) ===')
# Print all rows that have data in E, F, G, H, I, J, K, L
for row in range(1, ws_f.max_row+1):
    row_data = {}
    for col_letter in ['A','B','C','D','E','F','G','H','I','J','K','L']:
        from openpyxl.utils import column_index_from_string as c2i
        col_idx = c2i(col_letter)
        vf = ws_f.cell(row=row, column=col_idx).value
        vv = ws_v.cell(row=row, column=col_idx).value
        if vf is not None:
            row_data[col_letter] = (vf, vv)
    if any(k in row_data for k in ['E','F','G','H','I','J','K','L']):
        parts = []
        for k,v in row_data.items():
            vf, vv = v
            if isinstance(vf, str) and vf.startswith('='):
                parts.append(f'{k}:FORMULA({vf}=>{vv})')
            else:
                parts.append(f'{k}:{repr(vf)}')
        print(f'Row {row}: ' + ' | '.join(parts))
